programs.haiku:
"""Alternative-marking "or" (down_proj component 5070, layer 15).

This component writes a strongly negative value into the residual stream
on words that introduce an alternative: English "or" and "nor", and their
counterparts in other languages ("oder", "atau", "ou", "vagy", "или",
"либо", "或者", ...). Most other tokens, including "and", stay near zero.

The program predicts:
  - about -2.3 on an alternative word;
  - more negative (about -3.3) when it follows a comma, as in "a, or b";
  - less negative (about -1.3) when it follows a digit, as in math "1 or 3";
  - a small baseline of -0.05 everywhere else, the component's mean.

It is a token rule, not a model of the attention or the MLP that computes it.
It explains only the part of the variance carried by the alternative words.
The diffuse small activations on other tokens are left out.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

ALTERNATIVE_WORDS = frozenset(
    {"or", "nor", "oder", "atau", "ou", "vagy", "или", "либо", "бо", "或", "或者", "ili", "versus"}
)
BASELINE = -0.05


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip()
    if word not in ALTERNATIVE_WORDS:
        return carry, BASELINE
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if before == ",":
        return carry, -3.3
    if before.isdigit():
        return carry, -1.3
    return carry, -2.3

"""Coordinating and contrastive connectives that join clauses or list items.

A connective word (and, or, but, however, ...) gets a large activation when it
comes right after a comma or semicolon, i.e. when it opens a new clause or the
last item of a list ("red, green, and blue"). Contrastive connectives (but,
however, yet ...) fire even without the comma, especially sentence-initially.
Subordinating words that follow a comma (which, as, while, ...) fire weakly.
A coordinator without a comma before it is slightly negative; sentence-initial
"And"/"Or" are moderately positive. Everything else predicts 0.
"""
READS = ()

# coordinating conjunctions, English and common other languages
COORD = {"and", "or", "nor", "et", "und", "og", "och", "oder", "ou", "и", "а", "или", "或", "或者", "以及"}
# contrastive connectives
CONTRAST = {"but", "however", "yet", "though", "although", "whereas", "maar", "aber", "mais", "pero",
            "но", "однако", "但", "但是", "而", "ale", "ma", "然而"}
# subordinators and relative/list words that fire weakly after a comma
SUBORD = {"while", "which", "as", "etc", "with", "including", "who", "where", "such", "qui", "que", "so",
          "then", "because"}
COMMAS = {",", ";", "，", "、"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    first = len(prefix.token_ids) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    prev = "" if first else prefix.token_strings[-2].strip()
    after_comma = prev in COMMAS
    sentence_start = first or prev in {".", "!", "?", "\n", ""}
    if word in COORD:
        if after_comma:
            value = 5.0
        elif prefix.token_strings[-1].strip() in {"And", "Or"} and sentence_start:
            value = 2.0
        else:
            value = -0.25
    elif word in CONTRAST:
        value = 3.5 if after_comma else 2.0
    elif word in SUBORD:
        value = 1.1 if after_comma else 0.0
    else:
        value = 0.0
    return carry, value

"""Layer 15, MLP hidden unit 5085 (component p-82af68dd ... down_proj:5085).

This component is one MLP hidden unit's activation, scaled. Its value is small and
signed most of the time (about +-0.5), with rare large spikes. Almost all of its variance
is context-dependent, not lexical, so this program explains only a little of it.

What it does: it reads the current token alone and predicts
  - a high value on prediction and estimation words (predict, prediction, predicted,
    forecast, estimate, estimation, regression);
  - a mild negative value on verbs of noticing and inquiry (notice, observe, identify,
    investigate, explore, discover, see);
  - the average activation (about 0.04) on every other token.
"""

import re

READS = ()

PREDICT = {"predict", "prediction", "predicted", "predictor", "predictive", "predictions",
           "predicts", "forecast", "forecasting", "forecasts", "extrapolate", "extrapolation"}
ESTIMATE = {"estimate", "estimated", "estimates", "estimation", "regression"}
INQUIRE = {"notice", "noticed", "observe", "observed", "identify", "investigate", "explore",
           "discover", "discovered", "see", "examine", "analyze", "analyse"}

MEAN = 0.04


def step(carry, prefix, upstream):
    word = re.sub(r"[^a-z]", "", prefix.token_strings[-1].lower())
    if word in PREDICT:
        value = 1.0
    elif word in ESTIMATE:
        value = 0.7
    elif word in INQUIRE:
        value = -0.1
    else:
        value = MEAN
    return carry, float(value)

"""Predict layers.15.mlp.down_proj:5088 from the word class of the current token.

This component's activation is close to unstructured noise: std 0.28 around a mean
of 0.02, and no token, position or document feature explains more than a few percent
of it. Its causal importance is essentially zero, so it does almost nothing to the
model. The best simple description found is a small average per word class:

- quantifiers and "any/all/most/only/never"-type words run a little high (about +0.10);
- connectives and clause openers ("and", "that", "because", "if") run high (about +0.07);
- brackets, commas and code punctuation run high (about +0.07);
- articles and the prepositions "of", "in", "to" run slightly low (about -0.01);
- every other token sits near the overall mean (about +0.02).

Each class value is that class's mean activation on sampled training text. The class
lists are short word lists, not a full model of the component.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

QUANTIFIERS = {"any", "all", "most", "no", "only", "every", "each", "some", "both", "many", "never", "none", "always"}
CONNECTIVES = {"because", "that", "who", "through", "so", "as", "when", "if", "but", "and", "or", "which", "while", "since", "than"}
ARTICLES = {"the", "of", "The", "In", "a", "an", "there", "It", "This", "in", "to"}
PUNCTUATION = {",", "(", ")", ":", "=", "{", "}", "<", ">", "|", "/", "#", '"', "('"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip()
    if word in QUANTIFIERS:
        value = 0.10
    elif word in CONNECTIVES or word in PUNCTUATION:
        value = 0.07
    elif word in ARTICLES:
        value = -0.01
    else:
        value = 0.02
    return carry, float(value)

"""Layer 15, MLP neuron 5089 (down_proj component 5089): a "so / therefore" detector.

What it does: the component reads (almost only) one MLP hidden unit, and its activation
is large and positive on the word that states a CONSEQUENCE, the "so" in "it was cheap,
so I bought it", and "therefore", "thus", "hence" and their foreign equivalents. It is
near zero on most other tokens, and negative on contrast and reason words ("however",
"but", "because", "since"). This program predicts it from words alone:

  * consequence connectives: "so" after a comma, "and" or a closing bracket/quote,
    "therefore", "thus", "hence", ... -> large positive (about 4-5);
  * a comma that closes a fronted causal clause ("Since X,", "Due to X,", "Given X,",
    "If X,", "With X,") -> positive, the consequence clause is expected next;
  * a comma after a contrast opener ("However,", "Unlike X,") -> slightly negative;
  * hedges and inference verbs ("then", "than", "maybe", "perhaps", "means",
    "implies", "suggests") -> weakly positive;
  * "however", "but", "because", "since", "when", "if", "given" -> weakly negative;
  * everything else -> 0.

It does not model the many small activations spread over ordinary tokens, which is
most of the variance, so it explains only a small share of it.
"""

READS = ()

# Consequence connectives and their strength (mean activation on that word).
CONSEQUENCE = {
    "so": 5.0, "therefore": 5.0, "thus": 4.0, "hence": 4.5, "consequently": 2.5,
    "accordingly": 1.0, "因此": 5.0, "所以": 4.7, "ので": 4.4, "なので": 4.9,
    "だから": 4.6, "поэтому": 5.0, "donc": 2.9, "daher": 2.6,
}
# Words that open a fronted clause; a comma after it closes a causal or conditional lead-in.
STRONG_CAUSE = {"since", "because", "due", "depending", "given", "therefore", "hence",
                "accordingly", "consequently"}
WEAK_CAUSE = {"if", "when", "as", "with", "once", "without", "unless", "based", "according"}
CONTRAST = {"however", "unlike", "alternatively", "similarly", "moreover", "besides",
            "nevertheless", "unfortunately", "indeed", "but"}
HEDGES = {"then", "than", "maybe", "perhaps", "probably"}
INFERENCE = {"means", "implies", "implying", "suggests", "suggesting", "thereby", "why",
             "makes", "→", "⇒"}
CONTRAST_WORDS = {"however": -0.8, "but": -0.2, "because": -0.3, "since": -0.4,
                  "when": -0.2, "if": -0.15, "given": -0.2}
# A "so" right after one of these begins a consequence; elsewhere ("is so good") it is weak.
BEFORE_CONSEQUENCE = {",", "and", ")", '"', "."}


def word_value(word, prev, opener, commas):
    """Predicted activation of `word`, given the word before it, the sentence's first word
    (`opener`) and how many commas the sentence has had so far."""
    if word in CONSEQUENCE:
        if word == "so" and prev not in BEFORE_CONSEQUENCE:
            return 0.8
        return CONSEQUENCE[word]
    if word in HEDGES:
        return 0.9
    if word in INFERENCE:
        return 1.0
    if word in CONTRAST_WORDS:
        return CONTRAST_WORDS[word]
    if word == "," and commas == 0:
        if opener in STRONG_CAUSE:
            return 2.0
        if opener in WEAK_CAUSE:
            return 0.8
        if opener in CONTRAST:
            return -0.4
    return 0.0


def step(carry, prefix, upstream):
    # carry tracks the current sentence: its first word, its commas so far, the previous word.
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "opener": "", "commas": 0, "prev": ""}
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = word_value(word, carry["prev"], carry["opener"], carry["commas"])
    opener, commas = carry["opener"], carry["commas"]
    if "\n" in raw or word in {".", "!", "?"}:
        opener, commas = "", 0  # a sentence ends: the next word opens a new one
    elif word == ",":
        commas += 1
    elif opener == "" and any(ch.isalnum() for ch in word):
        opener = word
    return {"doc": doc, "opener": opener, "commas": commas, "prev": word}, float(value)

"""Relative-clause openers: the component fires on the word that opens a clause or
phrase attached to the noun just before it, as in "the data [that] we used",
"the room [you] rented", "the strains [used] in", "the first paper [to] call".

It is a rule over the current word and the word before it. WordNet tells whether a
word is a noun. Values are average activations measured on training text, in the
component's own units:
  * relative pronoun right after a noun ("data that", "a man who")          +3.4
  * subject pronoun right after a noun, a reduced relative ("room you")    +1.6
  * word ending in -ed right after a noun ("strains used", "paper given")  +1.1
  * preposition or "to" right after a noun ("place in", "paper to")        +0.5
  * "of" right after a noun ("amount of"), which pushes slightly negative  -0.3
  * relative pronoun right after a preposition ("in which", "to whom")     +1.8
  * the word right after a relative pronoun that follows a noun
    ("that we", "which they")                                              +1.6
Everything else is 0. Simple version: about 7% of the variance; the rest is
magnitude detail within these classes, which a lookup table would add a little.
"""

from wordnet import parts_of_speech

READS = ()

RELATIVE = {"that", "which", "who", "whom", "whose", "where", "que", "qui"}
PRONOUN = {"I", "you", "he", "she", "we", "they", "it"}
PREPOSITION = {"in", "on", "at", "for", "from", "by", "with", "to"}


def is_noun(word):
    return word.isalpha() and "noun" in parts_of_speech(word.lower())


def step(carry, prefix, upstream):
    n = len(prefix.token_ids)
    docs = prefix.document_ids
    words = [s.strip() for s in prefix.token_strings]
    cur = words[-1]
    # the two words before, only if they are in the same document
    prev = words[-2] if n > 1 and docs[-2] == docs[-1] else ""
    prev2 = words[-3] if n > 2 and docs[-3] == docs[-1] else ""
    noun_before = is_noun(prev)
    if cur in RELATIVE and noun_before:
        value = 3.4
    elif cur in PRONOUN and noun_before:
        value = 1.6
    elif cur.endswith("ed") and noun_before:
        value = 1.1
    elif cur in PREPOSITION and noun_before:
        value = 0.5
    elif cur == "of" and noun_before:
        value = -0.3
    elif cur in RELATIVE and prev in PREPOSITION:
        value = 1.8
    elif prev in RELATIVE and is_noun(prev2):
        value = 1.6
    else:
        value = 0.0
    return carry, float(value)
